on":"2026-10-06","source_url":"https://www.imdb.com/chart/toptv/"}},{"external_id":"tt33332385","title":"Widow's Bay","release_year":2026,"cover_url":"https://m.media-amazon.com/images/M/MV5BZDBiMWZlMDQtNzkzMi00YzQzLTkwNTUtNzYwOGY3YmUxNDJjXkEyXkFqcGc@._V1_.jpg","metadata":{"content_type_id":"series","uin_item_kind":"series","external_provider":"imdb","imdb_id":"tt33332385","imdb_url":"https://www.imdb.com/title/tt33332385/","imdb_rating":8.1,"imdb_votes":90359,"imdb_top_250_rank":null,"imdb_top_tv_250_as_of":"2026-09-30","series_lists":["emmy_comedy_30"],"series_list_ranks":{"emmy_comedy_30":1},"series_awards":[{"id":"emmy_comedy_30","label":"Emmy Komedi","years":[2026],"source_url":"https://www.televisionacademy.com/awards/nominees-winners/2026/outstanding-comedy-series","year":2026,"win_count":1}],"series_catalog_version":"2026-10-06","source_url":"https://www.imdb.com/chart/toptv/"}},{"external_id":"tt0157246","title":"Will & Grace","release_year":1998,"cover_url":"https://m.media-amazon.com/images/M/MV5BNDMwOTExZGUtNjFiMS00MzljLWJhMzYtYWFhMDUzOWUyYjMwXkEyXkFqcGc@._V1_.jpg","metadata":{"content_type_id":"series","uin_item_kind":"series","external_provider":"imdb","imdb_id":"tt0157246","imdb_url":"https://www.imdb.com/title/tt0157246/","imdb_rating":7.4,"imdb_votes":64869,"imdb_top_250_rank":null,"imdb_top_tv_250_as_of":"2026-09-30","series_lists":["emmy_comedy_30"],"series_list_ranks":{"emmy_comedy_30":17},"series_awards":[{"id":"emmy_comedy_30","label":"Emmy Komedi","years":[2000],"source_url":"https://www.televisionacademy.com/awards/nominees-winners/2026/outstanding-comedy-series","year":2000,"win_count":1}],"series_catalog_version":"2026-10-06","source_url":"https://www.imdb.com/chart/toptv/"}}]$json$::jsonb) as x(
      external_id text,title text,release_year integer,cover_url text,metadata jsonb
    )
  loop
    v_item_id := null;
    select item.id into v_item_id
    from public.seed_catalog_items item
    where item.status in ('active','pending','approved') and (
      coalesce(item.metadata->>'imdb_id','')=v_row.external_id
      or (lower(coalesce(item.external_source,item.metadata->>'external_provider',''))='imdb' and coalesce(item.external_id,'')=v_row.external_id)
      or ((item.seed_type_id=v_watch_type_id or item.item_kind in ('series','video') or item.metadata->>'content_type_id'='series')
          and public.canonical_normalize_v31(item.canonical_title)=public.canonical_normalize_v31(v_row.title)
          and (item.release_year is null or v_row.release_year is null or item.release_year=v_row.release_year))
    )
    order by
      case when coalesce(item.metadata->>'imdb_id','')=v_row.external_id or coalesce(item.external_id,'')=v_row.external_id then 0 else 1 end,
      case item.status when 'active' then 0 when 'approved' then 1 else 2 end,
      item.created_at,item.id
    limit 1;

    if v_item_id is null then
      begin
        insert into public.seed_catalog_items(
          seed_type_id,item_kind,canonical_title,release_year,cover_url,external_source,external_id,metadata,status
        ) values(
          v_watch_type_id,'series',v_row.title,v_row.release_year,v_row.cover_url,'imdb',v_row.external_id,v_row.metadata,'active'
        ) returning id into v_item_id;
      exception when others then
        select item.id into v_item_id
        from public.seed_catalog_items item
        where item.status in ('active','pending','approved')
          and public.canonical_normalize_v31(item.canonical_title)=public.canonical_normalize_v31(v_row.title)
        order by case item.status when 'active' then 0 when 'approved' then 1 else 2 end,item.created_at,item.id
        limit 1;
        if v_item_id is null then raise; end if;
        update public.seed_catalog_items
        set seed_type_id=v_watch_type_id,item_kind='series',cover_url=coalesce(nullif(cover_url,''),v_row.cover_url),
            release_year=coalesce(release_year,v_row.release_year),metadata=coalesce(metadata,'{}'::jsonb)||v_row.metadata,
            status='active',merged_into_id=null,updated_at=now()
        where id=v_item_id;
      end;
    else
      update public.seed_catalog_items
      set seed_type_id=v_watch_type_id,item_kind='series',
          cover_url=coalesce(nullif(cover_url,''),v_row.cover_url),
          release_year=coalesce(release_year,v_row.release_year),
          metadata=coalesce(metadata,'{}'::jsonb)||v_row.metadata,
          status='active',merged_into_id=null,updated_at=now()
      where id=v_item_id;
    end if;
  end loop;

  update public.seed_catalog_items item
  set metadata=coalesce(item.metadata,'{}'::jsonb)||jsonb_build_object(
    'imdb_id',source.metadata->>'imdb_id',
    'imdb_url',source.metadata->>'imdb_url',
    'imdb_rating',source.metadata->'imdb_rating',
    'imdb_votes',source.metadata->'imdb_votes',
    'imdb_top_250_rank',source.metadata->'imdb_top_250_rank',
    'imdb_top_tv_250_as_of',source.metadata->>'imdb_top_tv_250_as_of',
    'series_lists',source.metadata->'series_lists',
    'series_list_ranks',source.metadata->'series_list_ranks',
    'series_awards',source.metadata->'series_awards',
    'series_catalog_version','2026-10-06'
  ),updated_at=now()
  from public.seed_catalog_items source
  where source.metadata ? 'series_lists'
    and source.canonical_target_id is not null
    and source.canonical_target_id=item.canonical_target_id
    and item.status='active';

  update public.canonical_targets target
  set editorial_metadata=coalesce(target.editorial_metadata,'{}'::jsonb)||jsonb_build_object(
    'imdb_id',source.metadata->>'imdb_id',
    'imdb_rating',source.metadata->'imdb_rating',
    'imdb_top_250_rank',source.metadata->'imdb_top_250_rank',
    'series_lists',source.metadata->'series_lists',
    'series_list_ranks',source.metadata->'series_list_ranks',
    'series_awards',source.metadata->'series_awards',
    'series_catalog_version','2026-10-06'
  ),updated_at=now()
  from public.seed_catalog_items source
  where source.metadata ? 'series_lists' and source.canonical_target_id=target.id;

  select count(distinct metadata->>'imdb_id') into v_top_count
  from public.seed_catalog_items
  where status='active' and item_kind='series'
    and (metadata->>'imdb_top_250_rank')::integer between 1 and 250;
  if v_top_count <> 250 then
    raise exception 'IMDb Top 250 dizi doğrulaması başarısız: % kayıt',v_top_count;
  end if;
end;
$migration$;

notify pgrst,'reload schema';
commit;
